import type { BlockRegistry } from '@dragon-village/shared';
import { DRAGONS } from '@dragon-village/shared/data';
import { dragonOfEgg, potionFromItemId } from '@dragon-village/shared';

/** 물약 변형(potion.healing.long, splash_potion.x …)은 기본 물약 그림을 쓴다 (#175·유리병 자동 색칠) */
function potionSpriteId(id: string, atlas: IconSource): string {
  if (atlas.images.has(id)) return id;
  const p = potionFromItemId(id);
  return p ? `potion.${p.id}` : id;
}
import { renderBlockIcon } from './icons';

export interface IconSource {
  images: Map<string, ImageData>;
}

const cache = new Map<string, HTMLCanvasElement>();

/** 아이템 이름에서 안정된 색 (모양이 없는 아이템의 칩 색) */
function hue(id: string): number {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
  return h % 360;
}

/** 재료 색 (도구·주괴) */
const MATERIAL_COLOR: Record<string, string> = {
  wooden: '#a0703a',
  stone: '#8a8a8a',
  iron: '#d8d8d8',
  golden: '#f2c94c',
  gold: '#f2c94c',
  diamond: '#5fd8e8',
  netherite: '#4a3f4a',
  leather: '#8a5a3c',
  turtle: '#4f8a3a',
};

/**
 * 검 16×16 픽셀 그림 — 마인크래프트 검 모양(아빠 2026-10-07 "모든 무기를 마인크래프트 느낌으로"): 왼쪽 아래 손잡이 → 오른쪽 위 칼날,
 * 칼날은 밝은 면 2칸 + 어두운 테두리 1칸, 날밑은 칼날과 직각인 짧은 막대. b 칼날 밝음 · o 칼날 테두리 · g 날밑 · h 손잡이 · k 손잡이 끝
 */
const SWORD = [
  '.............bb.',
  '............bbo.',
  '...........bbo..',
  '..........bbo...',
  '.........bbo....',
  '........bbo.....',
  '.......bbo......',
  '......bbo.......',
  '..g..bbo........',
  '..gg.bo.........',
  '...ggo..........',
  '..hggg..........',
  '.hh.ggg.........',
  'hh..............',
  'kh..............',
  '................',
];

function shadeHex(hex: string, k: number): string {
  const n = parseInt(hex.slice(1), 16);
  const f = (c: number) => Math.max(0, Math.min(255, Math.round(c * k)));
  return `#${((f(n >> 16) << 16) | (f((n >> 8) & 255) << 8) | f(n & 255)).toString(16).padStart(6, '0')}`;
}

/** 검: 픽셀 하나하나 칸으로 그린다 (손에 들면 이 픽셀이 그대로 입체가 된다) */
/** 갑옷·방패·활 16×16 그림 (M8-2). m 재료색 · M 어두운 재료 · l 밝은 재료, 나머지 글자는 palette */
const HELMET = ['................', '................', '.....llllll.....', '....lmmmmmml....', '...lmmmmmmmml...', '...mmmmmmmmmm...', '...mmmmmmmmmm...', '...MmmmmmmmmM...', '...MM......MM...', '...MM......MM...', '...MMM....MMM...', '................', '................', '................', '................', '................'];
const CHESTPLATE = ['................', '..lll......lll..', '..lmml....lmml..', '..lmmm....mmml..', '..mmmmmmmmmmmm..', '..mmmmmmmmmmmm..', '..MmmmmmmmmmmM..', '...mmmmmmmmmm...', '...mmmmmmmmmm...', '...mmmmmmmmmm...', '...MmmmmmmmmM...', '...MMmmmmmmMM...', '...MMMMMMMMMM...', '................', '................', '................'];
const LEGGINGS = ['................', '...llllllllll...', '...mmmmmmmmmm...', '...mmmmmmmmmm...', '...mmmm..mmmm...', '...mmmm..mmmm...', '...mmm....mmm...', '...mmm....mmm...', '...mmm....mmm...', '...MmM....MmM...', '...MmM....MmM...', '...MMM....MMM...', '................', '................', '................', '................'];
const BOOTS = ['................', '................', '................', '................', '...lll....lll...', '...mmm....mmm...', '...mmm....mmm...', '...mmm....mmm...', '...mmmm...mmmm..', '..mmmmm..mmmmm..', '..MMMMM..MMMMM..', '................', '................', '................', '................', '................'];
const SHIELD = ['....iiiiiiii....', '...iwwwwwwwwi...', '...iwwwWWwwwi...', '...iwwWiiWwwi...', '...iwwWiiWwwi...', '...iwwwWWwwwi...', '...iwwwwwwwwi...', '...iwwwwwwwwi...', '....iwwwwwwi....', '....iwwwwwwi....', '.....iwwwwi.....', '......iwwi......', '.......ii.......', '................', '................', '................'];
/** 활 — 마인크래프트처럼 대각선: 활대가 왼쪽 위를 감싸고(H 바깥 어두운 나무 · h 나무 · g 손잡이), 시위(s)는 오른쪽 위 ↔ 왼쪽 아래 직선 */
const BOW = ['........HHHHH...', '......HHhhhhhH..', '.....Hhh.....h..', '....Hh......s...', '...Hg......s....', '..Hg......s.....', '.Hg......s......', '.Hh.....s.......', 'Hh.....s........', 'Hh....s.........', 'Hh...s..........', 'Hh..s...........', 'Hh.s............', '.Hh.............', '..H.............', '................'];
/** 쇠뇌 — 대각선 총몸(w 밝은 나무 · W 어두운 나무), 오른쪽 위에 직각으로 활대(h·H)와 시위(s), 가운데 쇠 걸쇠(i) */
const CROSSBOW = ['.......Hhh......', '........s.hhh...', '.........s...h..', '..........s..h..', '..........ii..h.', '..........wws.h.', '.........wW..s.H', '........wW....sH', '.......wW......H', '......wW........', '.....wW.........', '....wW..........', '...wW...........', '..wW............', '.wW.............', '................'];
const SHEARS = ['.............ii.', '............iii.', '...........iii..', '..........iii...', '.........iii....', '........iii.....', '.......iii......', '......iii.......', '.....iki........', '....hh.hh.......', '...hh...hh......', '..hh.....hh.....', '.hh.......hh....', 'hh.........hh...', '................', '................'];
/** 화살 — 마인크래프트처럼 대각선: 부싯돌 촉(f 밝음 · F 어두움), 막대(h), 깃(e 밝음 · E 어두움) */
const ARROW = ['.............Ff.', '............FffF', '...........hffF.', '..........hFF...', '.........h......', '........h.......', '.......h........', '......h.........', '.....h..........', '....h...........', '..Eeh...........', '.EeeE...........', 'Eee.E...........', 'eE..............', '................', '................'];
function drawPixels(ctx: CanvasRenderingContext2D, rows: readonly string[], u: number, palette: Record<string, string>): void {
  for (let y = 0; y < 16; y++)
    for (let x = 0; x < 16; x++) {
      const ch = rows[y]![x]!;
      if (ch === '.') continue;
      ctx.fillStyle = palette[ch] ?? '#ff00ff';
      ctx.fillRect(x * u, y * u, u + 0.5, u + 0.5);
    }
}
function armorPalette(material: string): Record<string, string> {
  return { m: material, M: shadeHex(material, 0.72), l: shadeHex(material, 1.22) };
}

function drawSword(ctx: CanvasRenderingContext2D, material: string, u: number): void {
  const color: Record<string, string> = { b: shadeHex(material, 1.12), o: shadeHex(material, 0.5), g: shadeHex(material, 0.72), h: '#6b4a2b', k: '#3d2a17' };
  for (let y = 0; y < 16; y++)
    for (let x = 0; x < 16; x++) {
      const ch = SWORD[y]![x]!;
      if (ch === '.') continue;
      ctx.fillStyle = color[ch] ?? material;
      ctx.fillRect(x * u, y * u, u + 0.5, u + 0.5);
    }
}

function materialOf(id: string): string {
  for (const k of Object.keys(MATERIAL_COLOR)) if (id.startsWith(k + '_') || id === k) return MATERIAL_COLOR[k];
  return '#b0b0b0';
}

function rrect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number): void {
  // roundRect 가 없는 브라우저도 있어서 직접 그린다
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

/** 블록 아닌 아이템을 종류별로 그린다 (아들이 그림을 그려 주면 텍스처로 바꾼다). s = 한 변 */
function drawItem(ctx: CanvasRenderingContext2D, id: string, name: string, s: number): void {
  const u = s / 16; // 16칸 격자
  ctx.lineWidth = Math.max(1, u * 0.8);
  ctx.strokeStyle = 'rgba(0,0,0,0.55)';
  const potion = id === 'water_bottle' || id === 'glass_bottle' || id.startsWith('potion.') || id.startsWith('splash_potion.') || id.startsWith('lingering_potion.');
  const isTool = /_(pickaxe|axe|sword|spear|shovel|hoe)$/.test(id);
  const isBucket = id === 'bucket' || id.endsWith('_bucket');
  const isDust = id.endsWith('_dust') || id === 'redstone' || id === 'sugar' || id === 'gunpowder' || id === 'glowstone_dust';
  const isIngot = id.endsWith('_ingot') || id === 'netherite' || id === 'gold_nugget';
  const isStick = id === 'stick' || id === 'blaze_rod' || id === 'breeze_rod' || id === 'bone';
  const isString = id === 'string';

  if (id.endsWith('_sword')) {
    drawSword(ctx, materialOf(id), u);
    return;
  }
  // 전투 장비 (M8-2)
  const armorKind = /_(helmet|chestplate|leggings|boots)$/.exec(id)?.[1];
  if (armorKind) {
    const rows = armorKind === 'helmet' ? HELMET : armorKind === 'chestplate' ? CHESTPLATE : armorKind === 'leggings' ? LEGGINGS : BOOTS;
    drawPixels(ctx, rows, u, armorPalette(materialOf(id)));
    return;
  }
  if (id === 'shield') {
    drawPixels(ctx, SHIELD, u, { i: '#d8d8d8', w: '#a0703a', W: '#5a3a1b' });
    return;
  }
  if (id === 'bow') {
    drawPixels(ctx, BOW, u, { H: '#4a3118', h: '#8a5a2b', g: '#5e3d1d', s: '#e8e8e8' });
    return;
  }
  if (id === 'crossbow') {
    drawPixels(ctx, CROSSBOW, u, { H: '#4a3118', h: '#8a5a2b', s: '#e8e8e8', i: '#c8c8c8', w: '#a0703a', W: '#5a3a1b' });
    return;
  }
  if (id === 'shears') {
    drawPixels(ctx, SHEARS, u, { i: '#d8d8d8', k: '#555555', h: '#8a5a2b' });
    return;
  }
  if (id === 'egg') {
    ctx.fillStyle = '#f3e7c9';
    ctx.beginPath();
    ctx.ellipse(8 * u, 8.5 * u, 4.2 * u, 5.4 * u, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,0.6)';
    ctx.fillRect(6 * u, 5 * u, u, 2 * u);
    return;
  }
  if (id === 'arrow') {
    drawPixels(ctx, ARROW, u, { f: '#cfcfcf', F: '#5c5c5c', h: '#8a5a2b', e: '#f2f2f2', E: '#9a9a9a' });
    return;
  }
  const egg = dragonOfEgg(id);
  if (egg) {
    // 드래곤 알: 드래곤 색 타원 + 점, 아래 어둡게
    const color = DRAGONS.find(egg)?.color ?? '#9a9a9a';
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(8 * u, 9 * u, 4.6 * u, 6 * u, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    ctx.beginPath();
    ctx.ellipse(8 * u, 12 * u, 4 * u, 2.6 * u, 0, 0, Math.PI);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    for (const [x, y] of [
      [6.2, 6.5],
      [9.5, 8],
      [7, 10.5],
    ]) ctx.fillRect(x * u, y * u, u, u);
    return;
  }
  if (potion) {
    // 병: 코르크 + 목 + 둥근 몸, 안에 액체
    const liquid = id === 'glass_bottle' ? null : id === 'water_bottle' ? '#3d7be6' : id.includes('healing') ? '#e64a4a' : id.includes('speed') ? '#7fd3ff' : id.includes('awkward') ? '#6b6ba8' : '#a24ae6';
    ctx.fillStyle = 'rgba(200,225,255,0.55)';
    rrect(ctx, 4 * u, 6 * u, 8 * u, 9 * u, 3 * u);
    ctx.fill();
    ctx.stroke();
    ctx.fillRect(6.5 * u, 2 * u, 3 * u, 4.5 * u);
    ctx.strokeRect(6.5 * u, 2 * u, 3 * u, 4.5 * u);
    ctx.fillStyle = '#b07a3a';
    ctx.fillRect(6 * u, 1 * u, 4 * u, 1.6 * u);
    if (liquid) {
      ctx.fillStyle = liquid;
      rrect(ctx, 5 * u, 9 * u, 6 * u, 5 * u, 2.4 * u);
      ctx.fill();
    }
    return;
  }
  if (isBucket) {
    // 마인크래프트 양동이 픽셀 그림(아빠가 보낸 그림, 2026-09-19): 어두운 테두리, 위 손잡이, 왼쪽 밝은 면, 안에 액체
    const liquid = id === 'water_bucket' ? ['#2f5fd6', '#4d86ff'] : id === 'lava_bucket' ? ['#e0561a', '#ffa030'] : id === 'milk_bucket' ? ['#e8e8e8', '#ffffff'] : null;
    const px = (x: number, y: number, w: number, h: number, color: string) => {
      ctx.fillStyle = color;
      ctx.fillRect(x * u, y * u, w * u, h * u);
    };
    const EDGE = '#2a2a2a';
    const DARK = '#5c5c5c';
    const MID = '#9a9a9a';
    const LIGHT = '#d9d9d9';
    // 손잡이
    px(6, 1, 4, 1, EDGE);
    px(5, 2, 1, 1, EDGE);
    px(10, 2, 1, 1, EDGE);
    px(4, 3, 1, 1, EDGE);
    px(11, 3, 1, 1, EDGE);
    // 테 (윗면 타원)
    px(3, 4, 10, 1, EDGE);
    px(2, 5, 12, 1, EDGE);
    px(3, 5, 10, 1, liquid ? liquid[0] : DARK);
    px(4, 5, 4, 1, liquid ? liquid[1] : MID);
    // 몸통: 위가 넓고 아래로 좁아진다
    px(2, 6, 12, 4, EDGE);
    px(3, 6, 10, 4, MID);
    px(3, 6, 2, 4, LIGHT);
    px(11, 6, 1, 4, DARK);
    px(3, 10, 10, 3, EDGE);
    px(4, 10, 8, 3, MID);
    px(4, 10, 2, 3, LIGHT);
    px(10, 10, 1, 3, DARK);
    px(4, 13, 8, 1, EDGE);
    px(5, 13, 6, 1, DARK);
    px(5, 14, 6, 1, EDGE);
    return;
  }
  if (isTool) {
    const head = materialOf(id);
    // 손잡이 (대각선)
    ctx.strokeStyle = '#8a5a2b';
    ctx.lineWidth = 2 * u;
    ctx.beginPath();
    ctx.moveTo(3 * u, 13 * u);
    ctx.lineTo(10.5 * u, 5.5 * u);
    ctx.stroke();
    ctx.fillStyle = head;
    ctx.strokeStyle = 'rgba(0,0,0,0.55)';
    ctx.lineWidth = Math.max(1, u * 0.8);
    if (id.endsWith('pickaxe')) {
      ctx.beginPath();
      ctx.moveTo(6 * u, 2.5 * u);
      ctx.quadraticCurveTo(11 * u, 1.5 * u, 14 * u, 6 * u);
      ctx.lineTo(12 * u, 7.5 * u);
      ctx.quadraticCurveTo(10.5 * u, 4.5 * u, 7 * u, 4.5 * u);
      ctx.closePath();
    } else if (id.endsWith('axe')) {
      ctx.beginPath();
      ctx.moveTo(9 * u, 2 * u);
      ctx.lineTo(14 * u, 4 * u);
      ctx.lineTo(13 * u, 8 * u);
      ctx.lineTo(9.5 * u, 6.5 * u);
      ctx.closePath();
    } else if (id.endsWith('sword')) {
      ctx.beginPath();
      ctx.moveTo(9 * u, 7 * u);
      ctx.lineTo(13.5 * u, 2.5 * u);
      ctx.lineTo(15 * u, 4 * u);
      ctx.lineTo(10.5 * u, 8.5 * u);
      ctx.closePath();
    } else if (id.endsWith('shovel')) {
      rrect(ctx, 9.5 * u, 1.5 * u, 5 * u, 6 * u, 2 * u);
    } else {
      // hoe
      ctx.beginPath();
      ctx.moveTo(9 * u, 3 * u);
      ctx.lineTo(14.5 * u, 3 * u);
      ctx.lineTo(14.5 * u, 5.5 * u);
      ctx.lineTo(11 * u, 5.5 * u);
      ctx.closePath();
    }
    ctx.fill();
    ctx.stroke();
    return;
  }
  if (isDust) {
    const c = id === 'glowstone_dust' ? '#ffd75e' : id === 'redstone' ? '#e03030' : id === 'sugar' ? '#f4f4f4' : id === 'gunpowder' ? '#666' : '#c8c8c8';
    ctx.fillStyle = c;
    const dots: [number, number, number][] = [
      [8, 11, 4.5],
      [5, 12.5, 3],
      [11.5, 12.5, 3],
      [7, 8, 2],
      [10.5, 8.5, 1.6],
      [8.5, 5.5, 1.2],
    ];
    for (const [x, y, r] of dots) {
      ctx.beginPath();
      ctx.arc(x * u, y * u, r * u, 0, Math.PI * 2);
      ctx.fill();
    }
    return;
  }
  if (isIngot) {
    ctx.fillStyle = materialOf(id.replace('_ingot', '').replace('gold_nugget', 'gold'));
    ctx.beginPath();
    ctx.moveTo(2 * u, 11 * u);
    ctx.lineTo(5 * u, 6 * u);
    ctx.lineTo(14 * u, 6 * u);
    ctx.lineTo(11 * u, 11 * u);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = 'rgba(0,0,0,0.18)';
    ctx.fillRect(2 * u, 11 * u, 9 * u, 2 * u);
    return;
  }
  if (isStick) {
    ctx.strokeStyle = id === 'blaze_rod' ? '#ffb02e' : id === 'bone' ? '#eee' : id === 'breeze_rod' ? '#9fd7ff' : '#8a5a2b';
    ctx.lineWidth = 2.2 * u;
    ctx.beginPath();
    ctx.moveTo(4 * u, 12.5 * u);
    ctx.lineTo(12 * u, 3.5 * u);
    ctx.stroke();
    return;
  }
  if (isString) {
    ctx.strokeStyle = '#f0f0f0';
    ctx.lineWidth = 1.4 * u;
    ctx.beginPath();
    ctx.moveTo(3 * u, 4 * u);
    ctx.bezierCurveTo(12 * u, 2 * u, 2 * u, 12 * u, 13 * u, 12 * u);
    ctx.stroke();
    return;
  }
  // 기본: 색 칩 + 이름 두 글자
  ctx.fillStyle = `hsl(${hue(id)} 45% 38%)`;
  rrect(ctx, 2 * u, 2 * u, 12 * u, 12 * u, 3 * u);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.35)';
  ctx.stroke();
  ctx.fillStyle = '#fff';
  ctx.font = `bold ${Math.round(s * 0.34)}px system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(Array.from(name.replace(/\s/g, '')).slice(0, 2).join(''), s / 2, s / 2);
}

/**
 * 아이템 아이콘. 블록이면 등각 블록 그림, 아니면 종류별 간단한 그림(병·양동이·도구·가루·주괴·막대·실), 그 외 색 칩 + 이름.
 * 같은 (id, size) 는 캐시. 화면 배율만큼 크게 그리고 CSS 로 size 에 맞춘다.
 */
export function itemIcon(id: string, size: number, registry: BlockRegistry, atlas: IconSource, name: string): HTMLCanvasElement {
  const key = `${id}@${size}`;
  const hit = cache.get(key);
  if (hit) return cloneCanvas(hit);
  const def = registry.find(id);
  let canvas: HTMLCanvasElement;
  const sprite = def && def.textures ? (def.shape === 'cross' || def.shape === 'rail' ? atlas.images.get(def.textures[0]) : def.shape === 'bed' || def.shape === 'sign' || def.shape === 'torch' ? atlas.images.get(id) : undefined) : undefined;
  if (sprite) {
    canvas = renderSpriteIcon(sprite, size); // 꽃·풀 (#180)·침대 (#188)·표지판 (#197)·횃불(아들 입체 그림 2026-10-19): 정육면체가 아니라 그림 그대로
  } else if (def && def.textures && def.shape === 'door' && atlas.images.get(def.textures[0]) && atlas.images.get(def.textures[2])) {
    canvas = renderDoorIcon(atlas.images.get(def.textures[0])!, atlas.images.get(def.textures[2])!, size); // 문 (#242): 윗칸 위에 아랫칸, 세로로 긴 그림
  } else if (def && def.textures && !dragonOfEgg(id)) {
    // 드래곤 알 16종은 블록이지만(#249) 아이콘은 아래 drawItem 의 드래곤 색 타원 그대로
    const missing = atlas.images.get('missing')!;
    canvas = renderBlockIcon(atlas.images.get(def.textures[0]) ?? missing, atlas.images.get(def.textures[1]) ?? missing, size);
  } else if (atlas.images.get(potionSpriteId(id, atlas))) {
    // 아이템 이름과 같은 16×16 그림이 textures/ 에 있으면 그대로 (#175, 아들 다이아몬드 그림) — 블록이 아닌 아이템은 이 길이 먼저
    canvas = renderSpriteIcon(atlas.images.get(potionSpriteId(id, atlas))!, size);
  } else {
    const dpr = Math.min(3, window.devicePixelRatio || 1);
    canvas = document.createElement('canvas');
    canvas.width = canvas.height = Math.round(size * dpr);
    canvas.style.width = canvas.style.height = `${size}px`;
    const ctx = canvas.getContext('2d')!;
    drawItem(ctx, id, name, size * dpr);
  }
  cache.set(key, canvas);
  return cloneCanvas(canvas);
}

/** 16×16 그림을 그대로 키운 아이콘 (픽셀 뭉개지 않게). 아들이 textures/<아이템>.png 를 넣으면 쓰인다 (#175) */
function renderSpriteIcon(img: ImageData, size: number): HTMLCanvasElement {
  const dpr = Math.min(3, window.devicePixelRatio || 1);
  const src = document.createElement('canvas');
  src.width = img.width;
  src.height = img.height;
  src.getContext('2d')!.putImageData(img, 0, 0);
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = Math.round(size * dpr);
  canvas.style.width = canvas.style.height = `${size}px`;
  const ctx = canvas.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;
  const pad = Math.round(size * dpr * 0.08);
  ctx.drawImage(src, pad, pad, canvas.width - pad * 2, canvas.height - pad * 2);
  return canvas;
}

/** 문 아이콘 (#242): 윗칸·아랫칸 16×16 두 장을 세로로 이어 16×32 로, 높이에 맞춰 가운데에 */
function renderDoorIcon(top: ImageData, bottom: ImageData, size: number): HTMLCanvasElement {
  const dpr = Math.min(3, window.devicePixelRatio || 1);
  const src = document.createElement('canvas');
  src.width = 16;
  src.height = 32;
  const sctx = src.getContext('2d')!;
  sctx.putImageData(top, 0, 0);
  sctx.putImageData(bottom, 0, 16);
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = Math.round(size * dpr);
  canvas.style.width = canvas.style.height = `${size}px`;
  const ctx = canvas.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;
  const pad = Math.round(size * dpr * 0.08);
  const h = canvas.height - pad * 2;
  const w = h / 2;
  ctx.drawImage(src, (canvas.width - w) / 2, pad, w, h);
  return canvas;
}

/** 복사본. 그림 픽셀은 dpr 배지만 화면 크기(css)는 size 로 — 안 그러면 고해상도 화면에서 2배로 커진다 */
function cloneCanvas(src: HTMLCanvasElement): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = src.width;
  c.height = src.height;
  c.style.width = src.style.width;
  c.style.height = src.style.height;
  c.getContext('2d')!.drawImage(src, 0, 0);
  return c;
}
