/**
 * 둥지의 드래곤들 (M6-3): 서버가 정한 자리(perch)에 복셀 드래곤을 세우고, 숨쉬기·살짝 둘러보기·콩콩 뛰기 idle 을 돌린다.
 * 위치·단계(아기/어른)·주인은 서버가 진실(nest 메시지). 여기서는 그리기만.
 * 복셀 한 칸 = 1/16 블록 — 아기 약 1.4×0.9×1.8 블록, 어른 약 2.4×1.4×2.7 블록(2배, 결정 #77).
 */
import { BOAT_SEAT_Y, CAMEL_SEAT_Y, CART_SEAT_Y, HORSE_SEAT_Y, type NestDragonInfo, PIG_SEAT_Y, RIDE_SEAT_Y } from '@dragon-village/shared';
import { PLAYER_SHADES, VOXEL } from './playerModel';
import { CAMEL_FRONT_SEAT_Z, animalVariant, animalVoxels, horseCoat, horseMarked, horseVoxels } from './animalModel';
import * as THREE from 'three';
import { nameSprite } from '../net/RemotePlayers';
import { type DragonStage, dragonVoxels } from './dragonModels';
import { buildVoxelGeometry } from './voxelGeometry';

export const VOXEL_SCALE = 1 / 16;

interface Entry {
  info: NestDragonInfo;
  group: THREE.Group;
  mesh: THREE.Mesh;
  label: THREE.Sprite;
  /** 쓰러져 쉴 때(#113) 머리 위 💤 */
  zz: THREE.Sprite;
  phase: number;
  height: number;
}

/** 쉬는 동안 납작하게 엎드린 높이 비율 (아빠 2026-10-06) */
const REST_FLAT = 0.55;

const geomCache = new Map<string, THREE.BufferGeometry>();
function geometryFor(dragon: string, stage: DragonStage): THREE.BufferGeometry {
  const key = `${dragon}/${stage}`;
  let g = geomCache.get(key);
  if (!g) {
    g = buildVoxelGeometry(dragonVoxels(dragon, stage), VOXEL_SCALE);
    geomCache.set(key, g);
  }
  return g;
}

const material = new THREE.MeshBasicMaterial({ vertexColors: true });

/** 드래곤 메시 하나 (지오메트리 공유). 탑승 표시용 */
export function dragonMesh(dragon: string, stage: DragonStage): THREE.Mesh {
  return new THREE.Mesh(geometryFor(dragon, stage), material);
}

const horseGeoms = new Map<string, THREE.BufferGeometry>();
const pigGeoms = new Map<string, THREE.BufferGeometry>();
/** 탈것 메시 (#166): 'horse' 면 말(털색은 말 번호로 — 타도 같은 말, #177), 'pig' 면 돼지(#185), 아니면 어른 드래곤 */
let boatGeom: THREE.BufferGeometry | null = null;
let cartGeom: THREE.BufferGeometry | null = null;
let camelGeom: THREE.BufferGeometry | null = null;
export function mountMesh(kind: string, id = 0): THREE.Mesh {
  if (kind === 'camel') {
    // 낙타 (2026-11-07): 앞자리(혹 앞)가 원점 위에 오게 뒤로 민다 — 뒷자리는 CAMEL_BACK 만큼 뒤
    if (!camelGeom) {
      camelGeom = buildVoxelGeometry(animalVoxels('camel', 0), VOXEL, PLAYER_SHADES);
      camelGeom.translate(0, 0, -CAMEL_FRONT_SEAT_Z * VOXEL);
    }
    return new THREE.Mesh(camelGeom, material);
  }
  if (kind === 'boat') {
    // 보트 (#209)
    if (!boatGeom) boatGeom = buildVoxelGeometry(animalVoxels('boat', 0), VOXEL, PLAYER_SHADES);
    return new THREE.Mesh(boatGeom, material);
  }
  if (kind === 'minecart') {
    // 수레 (#237)
    if (!cartGeom) cartGeom = buildVoxelGeometry(animalVoxels('minecart', 0), VOXEL, PLAYER_SHADES);
    return new THREE.Mesh(cartGeom, material);
  }
  if (kind === 'pig') {
    const v = animalVariant(id);
    const key = v < 0.6 ? 'temperate' : v < 0.8 ? 'cold' : 'warm';
    let g = pigGeoms.get(key);
    if (!g) {
      g = buildVoxelGeometry(animalVoxels('pig', v), VOXEL, PLAYER_SHADES);
      pigGeoms.set(key, g);
    }
    return new THREE.Mesh(g, material);
  }
  if (kind !== 'horse') return dragonMesh(kind, 'adult');
  const v = animalVariant(id);
  const coat = `${horseCoat(v)}${horseMarked(v) ? '+white' : ''}`; // 흰 무늬가 있는 말은 따로 (2026-11-07)
  let g = horseGeoms.get(coat);
  if (!g) {
    g = buildVoxelGeometry(horseVoxels(v), VOXEL, PLAYER_SHADES);
    horseGeoms.set(coat, g);
  }
  return new THREE.Mesh(g, material);
}
/** 탈것에 앉는 높이·방향: 말은 앞이 −z 라 안 돌리고, 드래곤은 머리가 +z 라 반 바퀴 */
export function mountSeat(kind: string): { seatY: number; turn: number } {
  return kind === 'camel' ? { seatY: CAMEL_SEAT_Y, turn: 0 } : kind === 'horse' ? { seatY: HORSE_SEAT_Y, turn: 0 } : kind === 'pig' ? { seatY: PIG_SEAT_Y, turn: 0 } : kind === 'boat' ? { seatY: BOAT_SEAT_Y, turn: 0 } : kind === 'minecart' ? { seatY: CART_SEAT_Y, turn: 0 } : { seatY: RIDE_SEAT_Y, turn: Math.PI };
}

/**
 * 내가 탄 드래곤 (M6-4): 내 발 아래 RIDE_SEAT_Y 에 어른 드래곤을 두고 내 시선 방향으로 돌린다.
 * 1인칭이라 머리·목·날개 끝이 화면 아래쪽에 보인다 (마인크래프트 말 타기처럼)
 */
export class MountView {
  private readonly group = new THREE.Group();
  private mesh: THREE.Mesh | null = null;
  private t = 0;

  constructor(scene: THREE.Scene) {
    this.group.visible = false;
    scene.add(this.group);
  }

  get active(): boolean {
    return this.mesh !== null;
  }

  private seat = { seatY: RIDE_SEAT_Y, turn: Math.PI };
  set(riding: { dragon: string; id: number } | null): void {
    if (this.mesh) {
      this.group.remove(this.mesh);
      this.mesh = null;
    }
    if (riding) {
      this.mesh = mountMesh(riding.dragon, riding.id);
      this.seat = mountSeat(riding.dragon);
      this.group.add(this.mesh);
    }
    this.group.visible = riding !== null;
  }

  /** 프레임마다: 내 위치·시선을 따라간다. 날개(몸통) 살짝 숨쉬기 */
  update(player: { pos: { x: number; y: number; z: number }; yaw: number }, dt: number): void {
    if (!this.mesh) return;
    this.t += dt;
    this.group.position.set(player.pos.x, player.pos.y - this.seat.seatY, player.pos.z);
    this.group.rotation.y = player.yaw + this.seat.turn; // 드래곤은 머리 +z → 내가 보는 -z 쪽, 말은 그대로
    this.mesh.scale.set(1, 1 + 0.015 * Math.sin(this.t * 2.5), 1);
  }
}

export class NestDragons {
  readonly group = new THREE.Group();
  private readonly entries = new Map<number, Entry>();
  private t = 0;

  constructor(scene: THREE.Scene) {
    scene.add(this.group);
  }

  get visible(): boolean {
    return this.group.visible;
  }
  set visible(v: boolean) {
    this.group.visible = v;
  }

  get count(): number {
    return this.entries.size;
  }

  /** 서버 목록과 맞춘다: 새로 온 것은 만들고, 없어진 것은 지우고, 단계·자리가 바뀐 것은 다시 만든다 */
  sync(list: readonly NestDragonInfo[]): void {
    const seen = new Set<number>();
    for (const info of list) {
      seen.add(info.id);
      const cur = this.entries.get(info.id);
      if (cur && cur.info.stage === info.stage && cur.info.perch.x === info.perch.x && cur.info.perch.z === info.perch.z && cur.info.owner === info.owner) {
        cur.info = info;
        continue;
      }
      if (cur) this.dispose(cur);
      this.entries.set(info.id, this.make(info));
    }
    for (const [id, e] of this.entries) if (!seen.has(id)) {
        this.dispose(e);
        this.entries.delete(id);
      }
  }

  private make(info: NestDragonInfo): Entry {
    const geom = geometryFor(info.dragon, info.stage);
    const mesh = new THREE.Mesh(geom, material);
    const height = geom.boundingBox ? geom.boundingBox.max.y : 1;
    const group = new THREE.Group();
    group.add(mesh);
    // 이름표는 주인 닉만 — 드래곤 종류는 모양·색으로 보이고, 긴 글자는 옆 드래곤과 겹친다 (패널 검증 2026-09-20)
    const label = nameSprite(info.owner, info.mine ? 'rgba(40,120,40,0.55)' : 'rgba(0,0,0,0.45)', 0.28);
    label.position.y = height + 0.25;
    group.add(label);
    const zz = nameSprite('💤', 'rgba(0,0,0,0)', 0.4);
    zz.position.y = height * REST_FLAT + 0.35;
    zz.visible = false;
    group.add(zz);
    group.position.set(info.perch.x + 0.5, info.perch.y, info.perch.z + 0.5);
    group.rotation.y = info.yaw;
    this.group.add(group);
    return { info, group, mesh, label, zz, phase: (info.id * 1.7) % (Math.PI * 2), height };
  }

  private dispose(e: Entry): void {
    this.group.remove(e.group);
    for (const s of [e.label, e.zz]) {
      (s.material as THREE.SpriteMaterial).map?.dispose();
      s.material.dispose();
    }
  }

  /**
   * 프레임마다: 숨쉬기(세로 2~3%), 가끔 콩콩, 천천히 둘러보기.
   * 쓰러져 쉬는 중(#113, `restingUntil` > now)이면 납작하게 엎드려 느리게 숨쉬고 머리 위에 💤 — 콩콩·둘러보기 없음. `now` 는 서버 시각
   */
  update(dt: number, now: number): void {
    if (!this.group.visible || this.entries.size === 0) return;
    this.t += dt;
    for (const e of this.entries.values()) {
      const t = this.t + e.phase;
      const resting = (e.info.restingUntil ?? 0) > now;
      if (resting) {
        const breath = 1 + 0.02 * Math.sin(t * 0.7);
        e.mesh.scale.set(1.06, REST_FLAT * breath, 1.06);
        e.mesh.rotation.z = 0.1; // 살짝 기운 채
        e.group.position.y = e.info.perch.y;
        e.group.rotation.y = e.info.yaw;
        e.zz.position.y = e.height * REST_FLAT + 0.35 + 0.06 * Math.sin(t * 1.2);
        e.label.position.y = e.height * REST_FLAT + 0.7;
      } else {
        const breath = 1 + 0.025 * Math.sin(t * 1.6);
        e.mesh.scale.set(1, breath, 1);
        e.mesh.rotation.z = 0;
        const hop = Math.max(0, Math.sin(t * 0.9)) ** 8; // 대부분 0, 가끔 살짝
        e.group.position.y = e.info.perch.y + hop * (e.info.stage === 'adult' ? 0.12 : 0.08);
        e.group.rotation.y = e.info.yaw + 0.18 * Math.sin(t * 0.35);
        e.label.position.y = e.height + 0.25;
      }
      e.zz.visible = resting;
    }
  }
}
